def seed(app, db, Module, Lesson, Question, Progress):
    """Create the course content using objects supplied by the Flask app.

    Accepting dependencies as arguments avoids importing app.py from this
    module and prevents a circular import during application startup.
    """
    with app.app_context():
        db.create_all()
        existing = Lesson.query.count()
        if existing == 30:
            return
        if existing:
            Question.query.delete()
            Progress.query.delete()
            Lesson.query.delete()
            Module.query.delete()
            db.session.commit()
        day=0
        for mi,(mtitle,mdesc,icon) in enumerate(MODULES):
            module=Module(title=mtitle,description=mdesc,icon=icon)
            db.session.add(module); db.session.flush()
            for j in range(6):
                day+=1
                title,summary,theory,example,visual,task,case,takeaways = DATA[day-1]
                lesson=Lesson(day=day,module_id=module.id,title=title,summary=summary,theory=theory,
                  example=example,visual=visual,task=task,case_study=case,takeaways=json.dumps(takeaways,ensure_ascii=False))
                db.session.add(lesson); db.session.flush()
                qs=[
                  ("Darsdagi asosiy tushuncha qaysi?",["Mavzuni dalil va maqsad bilan tushunish","Hisob-kitobni e'tiborsiz qoldirish","Faqat boshqalarga taqlid qilish"],0,"To‘g‘ri javob: mavzuni tushunib, dalil asosida qo‘llash kerak."),
                  ("Amaliy qaror oldidan nima qilish foydali?",["Vaziyatni tekshirish va variantlarni solishtirish","Barcha xavfni inkor qilish","Shoshilib qaror qilish"],0,"Avval vaziyatni aniqlash va variantlarni baholash kerak."),
                  ("Ushbu darsdan keyingi eng yaxshi qadam qaysi?",["Bilimni o‘z loyihangda kichik sinovdan o‘tkazish","Faqat nazariyani yodlash","Natijani o‘lchamaslik"],0,"Amaliy sinov bilimni mustahkamlaydi.")
                ]
                for prompt,opts,ans,explain in qs:
                    db.session.add(Question(day=day,prompt=prompt,options=json.dumps(opts,ensure_ascii=False),answer=ans,explanation=explain))
        for d in (1,2,3):
            db.session.add(Progress(day=d,completed=True,score=100))
        db.session.commit()

